      "기술·견적 문의 접수": "Technical & Quotation Inquiry",
      "온라인, 전화, 이메일을 통해 사용 조건과 요구 사양을 접수합니다.": "We receive usage conditions and required specifications via online form, phone, or email.",
      "제품 선정 상담": "Product Selection Consultation",
      "용도, 하중, 정밀도, 납기 조건을 검토해 최적 품목을 제안합니다.": "We review use case, load, precision, and delivery conditions to propose the best item.",
      "도면·기술자료 제공": "Drawings & Technical Resources",
      "도면, 카탈로그, 기술자료를 제공하고 적용 사양을 함께 검토합니다.": "We provide drawings, catalogs, and technical resources, then review application specifications together.",
