      "현장 설치와 초기 운전 과정에서 필요한 기술 지원을 제공합니다.": "We provide technical support for on-site installation and initial operation.",
      "유지보수·사후 대응": "Maintenance & After-Service",
      "납품 이후에도 운전 안정성과 유지보수를 위한 대응을 이어갑니다.": "After delivery, we continue supporting stable operation and maintenance.",
      "단순한 부품 납품에 그치지 않습니다": "We go beyond simply supplying parts",
      "현장에 실질적인 도움이 되는 기술지원": "Technical support that makes a practical difference on site",
      "고객이 현장에서 제품을 보다 편리하고 안정적으로 사용할 수 있도록 기술적 지원과 사후 대응까지 책임지고 있습니다.": "We provide technical support and after-service so customers can use products more conveniently and reliably on site.",
      "제품 선정부터 설치, 운영, 유지보수에 이르기까지 고객의 현장에 실질적인 도움을 드릴 수 있는 토탈 솔루션 제공을 목표로 합니다.": "From product selection to installation, operation, and maintenance, our goal is to deliver total solutions that genuinely support customer sites.",
